import os, json
import numpy as np

N = 26
R_MIN = 1e-6
SAFETY = 1e-9

P_CENTERS = 'storage/noesis/latest_centers.txt'
P_RADII   = 'storage/noesis/latest_radii.txt'
OUT_DIR   = 'storage/noesis/exports'
OUT_SWEEP = os.path.join(OUT_DIR, 'is_active_sweep_latest.json')
OUT_HIST  = os.path.join(OUT_DIR, 'histograms_latest.json')

TOLS = [1e-9, 5e-9, 1e-8, 2e-8]

def _ensure_dir(p):
    os.makedirs(p, exist_ok=True)

def _load_snapshot():
    try:
        c = np.loadtxt(P_CENTERS, dtype=float).reshape(N, 2)
        r = np.loadtxt(P_RADII, dtype=float).reshape(N,)
        assert np.all(r > 0)
        return c, r
    except Exception:
        # conservative fallback grid+hole
        centers = []
        radius = 0.08
        for i in range(5):
            for j in range(6):
                if len(centers) < N:
                    centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
        return np.array(centers, float), np.full(N, radius, float)

def _final_shrink(c, r, eps=SAFETY):
    return c, np.maximum(r - eps, R_MIN)

def _boundary_slacks(c, r):
    x = c[:,0]; y = c[:,1]
    return x - r, 1.0 - x - r, y - r, 1.0 - y - r

def _pair_slacks(c, r):
    diff = c[:,None,:] - c[None,:,:]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    return dist - (r[:,None] + r[None,:])

def _active_sets(c, r, tol):
    s_xL, s_xR, s_yB, s_yT = _boundary_slacks(c, r)
    sp = _pair_slacks(c, r)
    bset = set()
    for i in range(N):
        if s_xL[i] <= tol: bset.add((i,'xL'))
        if s_xR[i] <= tol: bset.add((i,'xR'))
        if s_yB[i] <= tol: bset.add((i,'yB'))
        if s_yT[i] <= tol: bset.add((i,'yT'))
    pset = set()
    for i in range(N):
        for j in range(i+1, N):
            if sp[i,j] <= tol:
                pset.add((i,j))
    return bset, pset, sp

def _degree_from_pairs(pset):
    deg = np.zeros(N, dtype=int)
    for (i,j) in pset:
        deg[i] += 1; deg[j] += 1
    hist = {}
    binc = np.bincount(deg)
    for k, v in enumerate(binc):
        if v > 0:
            hist[str(k)] = int(v)
    return hist

def _jaccard(a, b):
    if not a and not b:
        return 1.0
    inter = len(a & b)
    union = len(a | b)
    return (inter / union) if union > 0 else 0.0

def _quantiles(arr, qs=(0.0, 0.001, 0.01, 0.05, 0.1)):
    a = np.sort(arr.ravel())
    return {str(q): float(a[int(q*(len(a)-1))]) for q in qs}

def construct_packing():
    c, r = _load_snapshot()
    c, r = _final_shrink(c, r)

    _ensure_dir(OUT_DIR)

    # Compute per-tolerance summaries
    summaries = {}
    bsets = {}
    psets = {}
    pair_slack_quants = {}

    for tol in TOLS:
        bset, pset, sp = _active_sets(c, r, tol=tol)
        bsets[tol] = bset; psets[tol] = pset
        deg_hist = _degree_from_pairs(pset)
        summaries[tol] = {
            'tolerance': tol,
            'sum_radii': float(np.sum(r)),
            'active_boundary_count': len(bset),
            'active_pair_count': len(pset),
            'degree_histogram': deg_hist
        }
        iu = np.triu_indices(N, 1)
        pair_slack_quants[tol] = _quantiles(sp[iu], qs=(0.0, 1e-4, 1e-3, 1e-2, 5e-2, 0.1, 0.5))

    # Stability across tolerances (adjacent Jaccards)
    stability = []
    for a, b in zip(TOLS[:-1], TOLS[1:]):
        stability.append({
            'from_tol': a,
            'to_tol': b,
            'boundary_jaccard': _jaccard(bsets[a], bsets[b]),
            'pair_jaccard': _jaccard(psets[a], psets[b])
        })

    sweep = {
            'generated_at': None,
            'tolerances': TOLS,
            'summaries': summaries,
            'stability_adjacent': stability,
            'pair_slack_quantiles': pair_slack_quants
    }

    try:
        import time
        sweep['generated_at'] = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
    except Exception:
        pass

    # Write outputs
    try:
        with open(OUT_SWEEP, 'w') as f:
            json.dump(sweep, f, indent=2)
    except Exception:
        pass

    # Simple histogram-compatible file
    hist_out = {
        'tolerances': TOLS,
        'active_boundary_counts': [summaries[t]['active_boundary_count'] for t in TOLS],
        'active_pair_counts': [summaries[t]['active_pair_count'] for t in TOLS]
    }
    try:
        with open(OUT_HIST, 'w') as f:
            json.dump(hist_out, f, indent=2)
    except Exception:
        pass

    # Return the (shrunk) baseline for scoring
    return c.astype(float), r.astype(float)
